CREATE TABLE r1_object_upload_intents(tenant_id TEXT NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,org_id TEXT NOT NULL,object_key TEXT NOT NULL,metadata_digest TEXT NOT NULL,created_at TEXT NOT NULL,workspace_revision INTEGER NOT NULL,authorization_revision INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'reserved',PRIMARY KEY(tenant_id,id));
CREATE INDEX r1_upload_reconcile ON r1_object_upload_intents(tenant_id,state,id);
CREATE TABLE r1_provider_deliveries(tenant_id TEXT NOT NULL,id TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,recipient_id TEXT NOT NULL,state TEXT NOT NULL,receipt_id TEXT,receipt_digest TEXT,external_mode TEXT NOT NULL,source_namespace TEXT NOT NULL,payload TEXT NOT NULL,payload_digest TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER,owner_id TEXT NOT NULL,reason_code TEXT,org_id TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,source_namespace,source_id,source_revision,recipient_id));
INSERT INTO r1_provider_deliveries SELECT tenant_id,id,source_id,source_revision,recipient_id,state,receipt_id,receipt_digest,external_mode,source_namespace,payload,payload_digest,attempt,next_attempt_at,owner_id,reason_code,org_id FROM r1_deliveries WHERE source_namespace IS NOT NULL AND payload IS NOT NULL AND payload_digest IS NOT NULL AND owner_id IS NOT NULL AND org_id IS NOT NULL;
